--获取料理的buff=描述
function CookingUtils.GetBattleFoodEffectDesc(id)
    local t = {}
    local vo = CookingUtils.GetBattleCookingFoodVo(id)
    if not vo then
        return t
    end
    --table.insert(t, localize("持续战斗次数x_num_", {_num_ = vo.effectTimes}))
    local effectT = CookingUtils.GetBattleFoodEffectIds(id)
    local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
    for k, v in pairs(effectT) do 
        local vo = CookingUtils.GetCookingAttrVo(v)
        if vo then
            local buffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(vo.attAddBuffId)
            if buffVo then
                table.insert(t, buffVo.desc)
            end
        end
    end 
    return t
end

