---IsUnlockFood 是否解锁了食物
---@param id string 食物id
function CookingUtils.IsUnlockFood(id)
    if checkNumber(id) <= 0 then 
        return false
    end
    local type = GoodsUtils.GetIdType(id)
    local vo
    --好感度
    if type == Constants.IDType.GoodsFavorableFood then
        vo = CookingUtils.GetOrderFoodVo(id)
        local level = PhoneUtils.GetCatFavorabilityLevel(vo.catId)
        return checkNumber(level) >= checkNumber(vo.unlockLove)
    --战斗
    elseif type == Constants.IDType.GoodsBattleFood then
        vo = CookingUtils.GetBattleCookingFoodVo(id)
        return CookingUtils.IsHaveCookingRecipe(vo.menu)
    end
    return false
end

---GetUnlockFoodErr 是否解食物提示
---@param id string 食物id
function CookingUtils.GetUnlockFoodErr(id)
    if checkNumber(id) <= 0 then 
        return false
    end
    local type = GoodsUtils.GetIdType(id)
    local vo
    --好感度
    if type == Constants.IDType.GoodsFavorableFood then
        vo = CookingUtils.GetOrderFoodVo(id)
        local roleVo = PhoneUtils.GetCatVo(vo.catId)
        return localize("_name_好感度_num_级解锁", {_name_ = roleVo.name, _num_ = vo.unlockLove})
    --战斗
    elseif type == Constants.IDType.GoodsBattleFood then
        vo = CookingUtils.GetBattleCookingFoodVo(id)
        return ""
    end
    return ""
end

