    return CookingUtils.IsBlankQuest(systemId)
end

---IsBlankQuest 是否是黑名单关卡
---@param systemId string 模块id
function CookingUtils.IsBlankQuest(systemId)
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2018)
    for k, v in pairs(t) do
        local id = parse_number(v, "num")
        if id == checkNumber(systemId) then
            return true
        end 
    end
    return false
end

